package list;

import java.util.ArrayList;
import java.util.List;

/**
 * For-each loops whose loop variable is declared with var (like the ones generated by the gui2java template
 * GUI2JavaExecuteCommandMethod), so the type of the loop variable is inferred.
 */
public class ForEachVarLoop {

  public List<Integer> lengths(List<String> values) {
    ArrayList<Integer> result = new ArrayList<Integer>();
    for (var value : values) {
      result.add(value.length());
    }
    return result;
  }

  public static class Item {
    public int size = 1;
  }

  /** the inferred type of item is printed from the qualified type tree list.ForEachVarLoop.Item */
  public int totalSize(List<Item> items) {
    int total = 0;
    for (var item : items) {
      total += item.size;
    }
    return total;
  }

  public int sum(List<List<Integer>> nested) {
    int sum = 0;
    for (final var inner : nested) {
      for (var i : inner) {
        sum += i;
      }
    }
    return sum;
  }
}
